-- ----------sql1------------
SELECT D.FORENAME, D.SURNAME, R.NAME AS RACE_NAME, L.MILLISECONDS AS BEST_LAP_TIME FROM LAPTIMES L INNER JOIN DRIVERS D ON L.DRIVERID = D.DRIVERID INNER JOIN RACES R ON L.RACEID = R.RACEID WHERE L.MILLISECONDS = (SELECT MIN(MILLISECONDS) FROM LAPTIMES);
-- ----------sql2------------
-- NULL, 2147483648, 2147483648, NULL
SELECT T2.MILLISECONDS, T1.FORENAME, T1.SURNAME, T3.NAME FROM DRIVERS AS T1 INNER JOIN LAPTIMES AS T2 ON T1.DRIVERID = T2.DRIVERID INNER JOIN RACES AS T3 ON T2.RACEID = T3.RACEID ORDER BY T2.MILLISECONDS ASC LIMIT 1;

