-- 2147483648, 212
SELECT R.NAME AS RACE_NAME, DS.POINTS AS POINTS FROM DRIVERS AS D INNER JOIN DRIVERSTANDINGS AS DS ON D.DRIVERID = DS.DRIVERID INNER JOIN RACES AS R ON DS.RACEID = R.RACEID WHERE D.FORENAME = 'LEWIS' AND D.SURNAME = 'HAMILTON' ORDER BY R.YEAR ASC LIMIT 1;
-- ----------sql2------------
