SELECT SUM(DS.WINS) AS TOTAL_WINS, D.FORENAME, D.SURNAME FROM DRIVERSTANDINGS AS DS INNER JOIN DRIVERS AS D ON DS.DRIVERID = D.DRIVERID WHERE D.DOB = (SELECT MIN(DOB) FROM DRIVERS) GROUP BY D.DRIVERID, D.FORENAME, D.SURNAME;
-- ----------sql2------------
-- 0, NULL, 2147483648
SELECT SUM(T1.WINS),T2.FORENAME, T2.SURNAME FROM DRIVERSTANDINGS AS T1 INNER JOIN DRIVERS AS T2 ON T1.DRIVERID = T2.DRIVERID ORDER BY T2.DOB ASC LIMIT 1;

