-- ----------sql1------------
-- 2147483648
SELECT T.TEAM_LONG_NAME FROM TEAM AS T JOIN MATCH AS M ON T.TEAM_API_ID = M.HOME_TEAM_API_ID WHERE M.SEASON = '2015/2016' GROUP BY T.TEAM_API_ID HAVING SUM(CASE WHEN M.HOME_TEAM_GOAL - M.AWAY_TEAM_GOAL < 0 THEN 1 ELSE 0 END) > 0 ORDER BY SUM(CASE WHEN M.HOME_TEAM_GOAL - M.AWAY_TEAM_GOAL < 0 THEN 1 ELSE 0 END) ASC LIMIT 1;
-- ----------sql2------------
-- 2147483649
SELECT TEAMDETAILS.TEAM_LONG_NAME FROM MATCH AS MATCHDATA INNER JOIN TEAM AS TEAMDETAILS ON MATCHDATA.HOME_TEAM_API_ID = TEAMDETAILS.TEAM_API_ID WHERE MATCHDATA.SEASON = '2015/2016' AND MATCHDATA.HOME_TEAM_GOAL - MATCHDATA.AWAY_TEAM_GOAL < 0 GROUP BY MATCHDATA.HOME_TEAM_API_ID ORDER BY COUNT(*) ASC LIMIT 1;

