-- ----------sql1------------
-- 2147483650
-- 2147483648
-- 2147483649
-- 2147483651
SELECT DISTINCT P.PLAYER_NAME FROM PLAYER AS P INNER JOIN PLAYER_ATTRIBUTES AS PA ON P.PLAYER_API_ID = PA.PLAYER_API_ID WHERE PA.POTENTIAL = 61 AND PA.BALANCE = (SELECT MAX(BALANCE) FROM PLAYER_ATTRIBUTES);
-- ----------sql2------------
SELECT T1.PLAYER_NAME FROM PLAYER AS T1 INNER JOIN PLAYER_ATTRIBUTES AS T2 ON T1.PLAYER_API_ID = T2.PLAYER_API_ID WHERE T2.POTENTIAL = '61' ORDER BY T2.BALANCE DESC LIMIT 1;

