-- ----------sql1------------
-- 0
SELECT AVG(P.HEIGHT) AS AVERAGE_HEIGHT FROM COUNTRY C INNER JOIN LEAGUE L ON C.ID = L.COUNTRY_ID INNER JOIN TEAM T ON L.COUNTRY_ID = C.ID INNER JOIN PLAYER P ON T.TEAM_API_ID = P.PLAYER_API_ID WHERE C.NAME = 'ITALY';
-- ----------sql2------------
-- NULL
SELECT CAST(SUM(T1.HEIGHT) AS REAL) / COUNT(T1.ID) FROM PLAYER AS T1 INNER JOIN MATCH AS T2 ON T1.ID = T2.ID INNER JOIN COUNTRY AS T3 ON T2.COUNTRY_ID = T3.ID WHERE T3.NAME = 'ITALY';

