SELECT M.FIRST_NAME, M.LAST_NAME FROM INCOME I INNER JOIN MEMBER M ON I.LINK_TO_MEMBER = M.MEMBER_ID WHERE I.SOURCE = 'DUES' AND I.DATE_RECEIVED = (SELECT MIN(DATE_RECEIVED) FROM INCOME WHERE SOURCE = 'DUES') LIMIT 1;
-- ----------sql2------------
-- 2147483648, 2147483648
SELECT T1.FIRST_NAME, T1.LAST_NAME FROM MEMBER AS T1 INNER JOIN INCOME AS T2 ON T1.MEMBER_ID = T2.LINK_TO_MEMBER WHERE T2.SOURCE = 'DUES' ORDER BY T2.DATE_RECEIVED LIMIT 1;

