SELECT G.COUNTRY FROM TRANSACTIONS_1K AS T INNER JOIN GASSTATIONS AS G ON T.GASSTATIONID = G.GASSTATIONID WHERE T.PRODUCTID = 2 AND T.AMOUNT = 1 ORDER BY T.PRICE DESC LIMIT 1;
-- ----------sql2------------
-- 2147483649
SELECT T2.COUNTRY FROM TRANSACTIONS_1K AS T1 INNER JOIN GASSTATIONS AS T2 ON T1.GASSTATIONID = T2.GASSTATIONID WHERE T1.PRODUCTID = 2 ORDER BY T1.PRICE DESC LIMIT 1;
